import { test } from "node:test";
import assert from "node:assert/strict";
import { calcTotal } from "../src/pricing.ts";

test("calcTotal keeps the full total below 10 units", () => {
  assert.equal(calcTotal([
    { sku: "a", price: 2, qty: 4 },
    { sku: "b", price: 4, qty: 5 },
