});

test("calcTotal discounts carts with 10 or more total units by 10%", () => {
  for (const qty of [6, 7]) {
    assert.equal(calcTotal([
      { sku: "a", price: 2, qty: 4 },
      { sku: "b", price: 2, qty },
    ]), (4 + qty) * 2 * 0.9);
  }
});
